const SAFETY: Tip[] = [
  { id: 'sa-001', category: 'safety', title: 'Warm up first', contexts: ['pre-workout'],
    text: "Spend three to five minutes on easy movement before loaded sets: marching, arm circles, hip swings, and a few bodyweight squats." },
  { id: 'sa-002', category: 'safety', title: 'Know your stop signals', contexts: ['any', 'sore'],
    text: "Stop and rest if you feel sharp pain, numbness, dizziness, or chest discomfort. Those aren't push-through signals; check with a clinician if they persist." },
  { id: 'sa-003', category: 'safety', title: 'Clear the zone', contexts: ['pre-workout'],
    text: "Clear a space about six feet by six feet and check that the floor isn't slick before you start." },
  { id: 'sa-004', category: 'safety', title: 'Chair check', contexts: ['pre-workout'],
    text: "Before using a chair for step-ups or box squats, push it against a wall and test it with your weight first." },
  { id: 'sa-005', category: 'safety', title: 'Keep breathing', contexts: ['any'],
    text: "Exhale during the effort and inhale on the way back. Holding your breath can make you lightheaded." },
  { id: 'sa-006', category: 'safety', title: 'Set weights down safely', contexts: ['any'],
    text: "Lower dumbbells to the floor in front of you, never drop them near your feet, and keep your fingers clear of the plates." },
  { id: 'sa-007', category: 'safety', title: 'Dry hands', contexts: ['any'],
    text: "Wipe sweaty hands and dumbbell handles. A slick grip is an easy way to get hurt." },
  { id: 'sa-008', category: 'safety', title: 'Footing first', contexts: ['pre-workout', 'any'],
    text: "Train in sneakers or barefoot on a mat, not in slippery socks on a hard floor. Stable footing helps every move." },
  { id: 'sa-009', category: 'safety', title: 'Kind to knees', contexts: ['sore', 'any'],
    text: "If your knees complain, shorten your range, squat to a chair, or choose split squats over jumping. You can build back up gradually." },
  { id: 'sa-010', category: 'safety', title: 'Wrist relief', contexts: ['sore', 'any'],
    text: "If your wrists ache in push-ups, try fists, an incline against a counter, or spreading your fingers wide and pressing through your whole hand." },
  { id: 'sa-011', category: 'safety', title: 'Hinge safely', contexts: ['any', 'sore'],
    text: "On hinges, keep your spine long and move from the hips. If your lower back pinches, shorten the range and brace your abs." },
  { id: 'sa-012', category: 'safety', title: 'Stand up slowly', contexts: ['post-workout'],
    text: "After floor work, roll to your side, sit up, then stand. Quick changes in position can leave you lightheaded." },
  { id: 'sa-013', category: 'safety', title: 'Progress gradually', contexts: ['any', 'plateau', 'first-week'],
    text: "Add just a few reps or one set at a time, and change one thing per week. Joints and tendons adapt more slowly than muscles." },
  { id: 'sa-014', category: 'safety', title: 'Check with a pro', contexts: ['first-week', 'any'],
    text: "If you have an injury, a health condition, or you're coming back after a long break, check with your clinician before starting a new plan." },
  { id: 'sa-015', category: 'safety', title: 'Heat awareness', contexts: ['low-water', 'any'],
    text: "In a hot room, shorten the session, take more water breaks, and use a fan or open a window. Stop if you feel overheated." },
  { id: 'sa-016', category: 'safety', title: 'Be neighbor-friendly', contexts: ['evening', 'travel'],
    text: "If you share walls or floors, or the house is asleep, swap jumps for step-back versions to keep impact and noise down." },
  { id: 'sa-017', category: 'safety', title: 'Easing back in', contexts: ['missed-workout', 'first-week'],
    text: "After a break of two weeks or more, restart at about 70 percent of your old effort. The first week back should feel easy." },
  { id: 'sa-018', category: 'safety', title: 'Skip max efforts', contexts: ['any'],
    text: "Skip all-out max attempts at home. Controlled sets of 8 to 15 reps with good form are safer and still build plenty of strength." },
]

